cat > /app/output/index.html <<'HTML'
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>CreativeHub — Online Classes for Creatives</title>
  <style>
    :root {
      --bg-dark: #101320;
      --bg-dark-2: #171b2d;
      --text: #121212;
      --muted: #6d7587;
      --surface: #ffffff;
      --surface-soft: #f5f7fb;
      --primary: #5620c1;
      --accent-green: #55da9b;
      --accent-coral: #ff7d5c;
      --accent-yellow: #ffd166;
      --radius-lg: 22px;
      --radius-md: 16px;
      --radius-sm: 12px;
      --shadow: 0 18px 40px rgba(7, 12, 32, 0.12);
      --max: 1180px;
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; font-family: "Plus Jakarta Sans", "Inter", "Segoe UI", Arial, sans-serif; color: var(--text); background: #fff; }
    a { color: inherit; text-decoration: none; }
    img { display: block; max-width: 100%; }

    .container { width: min(var(--max), calc(100% - 2.2rem)); margin: 0 auto; }
    .section { padding: 5.5rem 0; }

    .topbar {
      position: sticky; top: 0; z-index: 40;
      backdrop-filter: blur(10px);
      background: rgba(16, 19, 32, 0.82);
      border-bottom: 1px solid rgba(255,255,255,.08);
    }
    .nav { min-height: 74px; display: flex; align-items: center; justify-content: space-between; gap: 1rem; color: #fff; }
    .brand { display:flex; align-items:center; gap:.6rem; font-weight: 800; font-size: 1.15rem; }
    .brand-badge { width: 34px; height: 34px; border-radius: 10px; background: linear-gradient(145deg, var(--accent-green), #76ffca); color:#0d2219; display:grid; place-items:center; font-weight:900; }
    .nav-links { display:flex; gap: 1.2rem; align-items:center; }
    .nav-links a { opacity:.9; }
    .nav-links a:hover { opacity:1; }
    .btn-nav { padding: .7rem 1rem; border-radius: 999px; border: 1px solid rgba(255,255,255,.18); }
    .btn-nav.primary { background: var(--accent-coral); border-color: transparent; color:#1f1010; font-weight:700; }

    .hero-wrap {
      background: radial-gradient(1000px 500px at 15% -10%, #2a3570 10%, transparent 55%),
                  radial-gradient(680px 380px at 88% 8%, #40358f 15%, transparent 55%),
                  linear-gradient(160deg, var(--bg-dark), var(--bg-dark-2));
      color: #fff;
      padding-bottom: 4.2rem;
    }
    .hero { padding: 4rem 0 2.2rem; display:grid; grid-template-columns: 1.05fr .95fr; gap: 2rem; align-items: center; }
    .eyebrow { display:inline-flex; align-items:center; gap:.5rem; background: rgba(255,255,255,.1); border:1px solid rgba(255,255,255,.16); border-radius: 999px; padding: .35rem .8rem; font-size: .83rem; margin-bottom: 1rem; }
    h1 { margin: .2rem 0 1rem; font-size: clamp(2rem, 4.6vw, 4rem); line-height: 1.05; letter-spacing: -.02em; }
    .subtitle { margin: 0 0 1.6rem; color: #d8dcf7; font-size: 1.08rem; max-width: 52ch; }
    .hero-actions { display:grid; gap: .8rem; max-width: 440px; }
    .cta { height: 54px; border-radius: 14px; border: none; font-weight: 800; font-size: 1rem; cursor:pointer; transition: transform .2s ease, box-shadow .2s ease, opacity .2s; }
    .cta:hover { transform: translateY(-2px); box-shadow: 0 10px 24px rgba(0,0,0,.22); }
    .cta.google { background: #fff; color:#111; }
    .cta.email { background: var(--accent-green); color:#0c1f17; }
    .legal { margin-top: .9rem; color: #b8bfdf; font-size: .8rem; line-height: 1.5; }

    .hero-card {
      background: #fff; color:#111; border-radius: var(--radius-lg); padding: 1rem; box-shadow: var(--shadow);
    }
    .hero-card .cover { aspect-ratio: 16/10; border-radius: 16px; background: linear-gradient(135deg, #ffd6cc, #ff875f 45%, #5620c1); display:grid; place-items:end start; padding:1rem; font-weight:800; color:#fff; font-size:1.2rem; }
    .mini-row { display:flex; gap:.7rem; margin-top:.8rem; }
    .mini-pill { background: #f2f5fb; border-radius: 999px; padding: .38rem .7rem; font-size: .78rem; color:#3a4260; }

    .category-strip { display:flex; gap:.65rem; flex-wrap: wrap; margin-top: 1rem; }
    .cat-pill { border-radius: 999px; border:1px solid rgba(255,255,255,.26); color:#fff; background: rgba(255,255,255,.08); padding:.5rem .9rem; font-size:.85rem; transition: .2s; }
    .cat-pill:hover { background: rgba(255,255,255,.18); }

    .features-grid { display:grid; grid-template-columns: repeat(3,1fr); gap:1rem; }
    .feature { background: var(--surface-soft); border-radius: var(--radius-md); padding: 1.2rem; }
    .feature h3 { margin: .2rem 0 .5rem; }
    .feature p { margin:0; color: var(--muted); }

    .stats-band { background: #171328; color:#fff; border-radius: var(--radius-lg); padding: 2.2rem; display:grid; grid-template-columns: repeat(4,1fr); gap:1rem; }
    .stat-value { font-size: clamp(1.8rem, 3vw, 3rem); font-weight: 900; letter-spacing: -.02em; }
    .stat-label { color:#cad0ef; margin-top:.35rem; font-size:.9rem; }

    .sec-head { display:flex; justify-content:space-between; align-items:end; gap:1rem; margin-bottom:1.15rem; }
    .sec-head h2 { margin:0; font-size: clamp(1.6rem, 3.2vw, 2.3rem); }
    .sec-head p { margin:0; color: var(--muted); max-width: 48ch; }

    .tabs { display:flex; gap:.6rem; flex-wrap: wrap; margin-bottom: 1rem; }
    .tab { border:1px solid #d9dfef; background:#fff; color:#24304f; border-radius:999px; padding:.55rem .95rem; font-weight:700; cursor:pointer; }
    .tab.active { background: #1f2745; border-color:#1f2745; color:#fff; }

    .course-grid { display:grid; grid-template-columns: repeat(3,1fr); gap:1rem; }
    .course-card { border:1px solid #e7ebf5; border-radius: 16px; overflow:hidden; background:#fff; transition: .2s; }
    .course-card:hover { transform: translateY(-4px); box-shadow: var(--shadow); }
    .thumb { aspect-ratio: 16/9; padding: .9rem; display:flex; align-items:end; color:#fff; font-weight:800; }
    .course-body { padding: .9rem; }
    .course-title { margin:0 0 .5rem; font-size: 1rem; line-height:1.35; }
    .meta { color:#5f6881; font-size:.86rem; display:flex; gap:.65rem; flex-wrap:wrap; }

    .feed-grid, .testimonials, .teams-grid { display:grid; grid-template-columns: repeat(3,1fr); gap:1rem; }
    .feed-card, .quote, .team-card { background:#fff; border:1px solid #e7ebf5; border-radius:16px; padding:1rem; }
    .quote p { margin-top:0; color:#27314d; }

    .teachers-shell { position: relative; }
    .teachers-track { display:flex; gap:1rem; overflow-x:auto; scroll-behavior:smooth; padding-bottom:.4rem; }
    .teachers-track::-webkit-scrollbar { height: 8px; }
    .teachers-track::-webkit-scrollbar-thumb { background:#cfd7ec; border-radius:20px; }
    .teacher { min-width: 250px; border:1px solid #e7ebf5; border-radius:16px; background:#fff; padding:1rem; }
    .avatar { width:56px; height:56px; border-radius:50%; display:grid; place-items:center; color:#fff; font-weight:800; margin-bottom:.7rem; }
    .car-nav { position:absolute; top:-3.2rem; right:0; display:flex; gap:.5rem; }
    .icon-btn { width:38px; height:38px; border-radius:999px; border:1px solid #d6ddf0; background:#fff; cursor:pointer; }

    .faq { border:1px solid #e7ebf5; border-radius:16px; overflow:hidden; }
    .faq-item + .faq-item { border-top:1px solid #e7ebf5; }
    .faq-q { width:100%; text-align:left; border:none; background:#fff; padding:1rem 1.1rem; font-size:1rem; font-weight:700; display:flex; justify-content:space-between; cursor:pointer; }
    .faq-a { max-height:0; overflow:hidden; transition:max-height .25s ease; background:#fafbff; }
    .faq-a p { margin:0; padding: 0 1.1rem 1rem; color:#4c5877; }
    .faq-item.open .faq-a { max-height: 180px; }

    footer { background:#101320; color:#d2d8f8; padding:2.4rem 0; margin-top: 4rem; }
    .foot { display:flex; justify-content:space-between; gap:1rem; flex-wrap:wrap; }

    @media (max-width: 980px) {
      .hero { grid-template-columns: 1fr; }
      .features-grid, .course-grid, .feed-grid, .testimonials, .teams-grid { grid-template-columns: repeat(2,1fr); }
      .stats-band { grid-template-columns: repeat(2,1fr); }
    }
    @media (max-width: 640px) {
      .nav-links { display:none; }
      .section { padding: 4rem 0; }
      .features-grid, .course-grid, .feed-grid, .testimonials, .teams-grid, .stats-band { grid-template-columns: 1fr; }
      .hero-actions .cta { width: 100%; }
      .faq-q { font-size:.95rem; }
    }
  </style>
</head>
<body>
  <header class="topbar">
    <div class="container nav">
      <div class="brand"><span class="brand-badge">C</span> CreativeHub</div>
      <nav class="nav-links">
        <a href="#courses">Browse</a>
        <a href="#">Sign In</a>
        <a class="btn-nav primary" href="#hero">Sign Up</a>
      </nav>
    </div>
  </header>

  <section class="hero-wrap" id="hero">
    <div class="container hero">
      <div>
        <span class="eyebrow">⚡ 7-day free trial</span>
        <h1>Creative Classes Taught by the Best Creative Pros</h1>
        <p class="subtitle">Get 7 free days of CreativeHub. Learn illustration, design, filmmaking, animation, and more through practical classes from working creators.</p>
        <div class="hero-actions">
