    </div>
  </section>

  <footer>
    <div class="container foot">
      <div><strong>CreativeHub</strong><div>© 2026 CreativeHub, Inc.</div></div>
      <div>Terms · Privacy · Contact</div>
    </div>
  </footer>

  <script>
    const courses = {
      "Featured": [
        { title: "Kickstart your Creativity with Procreate: 20 Fun Drawings for Beginners and Beyond", instructor: "Alice Monroe", students: "24,890", duration: "5h 10m", bg: "linear-gradient(130deg,#ff9d7b,#ff7d5c,#5620c1)" },
        { title: "Social Media Content Creation in Canva: From Beginner to Advanced", instructor: "Diego Vega", students: "18,220", duration: "3h 50m", bg: "linear-gradient(130deg,#5620c1,#2d4fb0,#55da9b)" },
        { title: "Landscapes: A Free-Flow Watercolour Masterclass", instructor: "Mina Joshi", students: "13,520", duration: "4h 05m", bg: "linear-gradient(130deg,#55da9b,#1fbf87,#0f4f44)" },
        { title: "Figma UI UX Design Advanced: Become a Pro", instructor: "Priya Shah", students: "21,340", duration: "6h 12m", bg: "linear-gradient(130deg,#232b4d,#445ca9,#8fa8ff)" },
        { title: "How to Draw: A Beginner's Guide", instructor: "Rosa Ahmed", students: "33,140", duration: "2h 45m", bg: "linear-gradient(130deg,#ffd166,#ff9f1c,#ff7d5c)" },
        { title: "Learn Video Editing With Premiere Pro For Beginners", instructor: "Leo Park", students: "16,890", duration: "4h 48m", bg: "linear-gradient(130deg,#431a85,#5620c1,#ff7d5c)" }
      ],
      "Music": [
        { title: "Bedroom Producer Essentials", instructor: "Noah Lin", students: "8,210", duration: "3h 15m", bg: "linear-gradient(130deg,#3d2c8d,#6a4de1,#ef8bff)" },
        { title: "Mixing Vocals That Cut Through", instructor: "Mila Reed", students: "7,980", duration: "2h 58m", bg: "linear-gradient(130deg,#1f2a44,#2e6db5,#55da9b)" },
        { title: "Songwriting for Visual Storytellers", instructor: "Arun Patel", students: "6,440", duration: "2h 30m", bg: "linear-gradient(130deg,#ff9a6b,#ff7d5c,#d14dcb)" }
      ],
      "Drawing & Painting": [
        { title: "Character Sketching from Shape Language", instructor: "Alice Monroe", students: "12,220", duration: "3h 44m", bg: "linear-gradient(130deg,#ffb97a,#ff7d5c,#9a3fd1)" },
        { title: "Ink & Wash Techniques", instructor: "Rosa Ahmed", students: "9,430", duration: "2h 55m", bg: "linear-gradient(130deg,#1f2745,#324f88,#6ddcc3)" },
        { title: "Color Theory in Practice", instructor: "Mina Joshi", students: "14,710", duration: "3h 05m", bg: "linear-gradient(130deg,#ffd166,#f79d3d,#ff7d5c)" }
      ],
      "Marketing": [
        { title: "Brand Storytelling for Social Platforms", instructor: "Diego Vega", students: "10,320", duration: "2h 42m", bg: "linear-gradient(130deg,#ff7d5c,#ffb089,#5620c1)" },
        { title: "Creator Portfolio Funnels", instructor: "Nina Cole", students: "8,860", duration: "2h 28m", bg: "linear-gradient(130deg,#1d3357,#2f6fb4,#55da9b)" },
        { title: "Designing High-Converting Thumbnails", instructor: "Kira Tan", students: "11,570", duration: "2h 16m", bg: "linear-gradient(130deg,#5620c1,#7d44dc,#f5a6ff)" }
      ],
      "Animation": [
        { title: "2D Motion Principles for Beginners", instructor: "Leo Park", students: "15,340", duration: "3h 35m", bg: "linear-gradient(130deg,#ffca67,#ff9f1c,#ff7d5c)" },
        { title: "After Effects Workflow Sprint", instructor: "Kira Tan", students: "13,040", duration: "4h 08m", bg: "linear-gradient(130deg,#2f2f8f,#5620c1,#8896ff)" },
        { title: "Storyboarding for Animated Scenes", instructor: "Rosa Ahmed", students: "9,990", duration: "2h 50m", bg: "linear-gradient(130deg,#20464f,#2d7b84,#55da9b)" }
      ]
    };

    const courseGrid = document.getElementById('courseGrid');
    const tabs = document.querySelectorAll('.tab');

    function renderCourses(tab) {
      courseGrid.innerHTML = '';
      courses[tab].forEach((course) => {
        const card = document.createElement('article');
        card.className = 'course-card';
        card.innerHTML = `
          <div class="thumb" style="background:${course.bg}">${course.duration}</div>
          <div class="course-body">
            <h3 class="course-title">${course.title}</h3>
            <div class="meta">
              <span>${course.instructor}</span>
              <span>• ${course.students} students</span>
            </div>
          </div>
        `;
        courseGrid.appendChild(card);
      });
    }

    tabs.forEach((tab) => {
      tab.addEventListener('click', () => {
        tabs.forEach((t) => {
          t.classList.remove('active');
          t.setAttribute('aria-selected', 'false');
        });
        tab.classList.add('active');
        tab.setAttribute('aria-selected', 'true');
        renderCourses(tab.dataset.tab);
      });
    });

    renderCourses('Featured');

    const faqItems = document.querySelectorAll('.faq-item');
    faqItems.forEach((item) => {
      item.querySelector('.faq-q').addEventListener('click', () => {
        const isOpen = item.classList.contains('open');
        faqItems.forEach((el) => el.classList.remove('open'));
        if (!isOpen) item.classList.add('open');
      });
    });

    const teacherTrack = document.getElementById('teacherTrack');
    document.getElementById('teacherPrev').addEventListener('click', () => teacherTrack.scrollBy({ left: -280, behavior: 'smooth' }));
